# Send-flow rework (#89): draft documents + draft-token auth.
#
# Hand-written (not autogenerated): the draft_token field is unique
# with a callable default, and Django's autodetector cannot populate
# unique values for existing rows on its own - it stops at an
# interactive prompt. So the token lands in three steps: add the
# column with a plain default, fill a unique token per existing row,
# then switch the default to the generator and add the constraint.

import secrets

import django.db.models.deletion
from django.db import migrations, models

import apps.signing.models


def set_draft_tokens(apps, schema_editor):
    Document = apps.get_model("signing", "Document")
    for doc in Document.objects.filter(draft_token=""):
        doc.draft_token = secrets.token_urlsafe(32)
        doc.save(update_fields=["draft_token"])


